#!/usr/bin/env node
import fs from 'node:fs';
import { calculateLiuyao } from './index.js';
function parseArgs() {
    const args = {};
    for (const value of process.argv.slice(2)) {
        const match = value.match(/^--([^=]+)=(.*)$/);
        if (match)
            args[match[1]] = match[2];
    }
    return args;
}
function number(value, label) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed))
        throw new Error(`${label}必须是数字`);
    return parsed;
}
function parseCastTime(args) {
    const keys = ['year', 'month', 'day', 'hour', 'minute'];
    const supplied = keys.filter(key => args[key] !== undefined);
    if (!supplied.length)
        return undefined;
    if (supplied.length !== keys.length)
        throw new Error('指定起卦时间时必须同时提供 year、month、day、hour、minute');
    return {
        year: number(args.year, 'year'),
        month: number(args.month, 'month'),
        day: number(args.day, 'day'),
        hour: number(args.hour, 'hour'),
        minute: number(args.minute, 'minute'),
        timeZone: args.timeZone === undefined ? 8 : number(args.timeZone, 'timeZone'),
    };
}
function main() {
    const args = parseArgs();
    if (!args.question || !args.category || !args.method) {
        throw new Error('用法: --question=具体事项 --category=career --method=time|numbers [--numbers=12,35,8] [--year=2026 ...] [--output=chart.json]');
    }
    const input = {
        question: args.question,
        category: args.category,
        method: args.method,
        numbers: args.numbers?.split(',').map(value => Number(value.trim())),
        castTime: parseCastTime(args),
        usefulGodRelative: args.usefulGodRelative,
    };
    const result = calculateLiuyao(input);
    const json = JSON.stringify(result, null, 2) + '\n';
    if (args.output)
        fs.writeFileSync(args.output, json, 'utf8');
    else
        process.stdout.write(json);
}
try {
    main();
}
catch (error) {
    process.stderr.write(`六爻排盘失败：${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
}
